/**
 * This test confirms that the expected thread context classloader
 * is returned from the getContextClassLoader method.
 */
@Test
public void getContextClassLoader() throws MalformedURLException {
    final ClassLoader nullLoader = null;
    final ClassLoader jvmAppLoader = ClassLoader.getSystemClassLoader();
    final ClassLoader jvmExtLoader = jvmAppLoader.getParent();
    final ClassLoader testClassLoader = ClassLoaderUtilsTest.class.getClassLoader();
    final ClassLoader clildLoader = new URLClassLoader(new URL[] { new URL("file:/.") });
    final ClassLoader previousTCCL = Thread.currentThread().getContextClassLoader();
    try {
        // TCCL = null
        setTCCL(nullLoader);
        assertEquals("TCCL == null; wrong loader returned; expected JVM App loader", jvmAppLoader, ClassLoaderUtils.getContextClassLoader());
        // TCCL = JVM App CL
        setTCCL(jvmAppLoader);
        assertEquals("TCCL == JVM App loader; wrong loader returned; expected JVM App loader", jvmAppLoader, ClassLoaderUtils.getContextClassLoader());
        // TCCL = JVM Ext CL
        setTCCL(jvmExtLoader);
        assertEquals("TCCL == JVM Ext loader; wrong loader returned; expected JVM Ext loader", jvmExtLoader, ClassLoaderUtils.getContextClassLoader());
        // TCCL = This test class loader (which is likely also the JVM App CL)
        setTCCL(testClassLoader);
        assertEquals("TCCL == this test laoder; wrong loader returned; expected JVM App loader", testClassLoader, ClassLoaderUtils.getContextClassLoader());
        // TCCL = a random child classloader
        setTCCL(clildLoader);
        assertEquals("TCCL == random child loader, wrong loader returned; expected child of test class loader", clildLoader, ClassLoaderUtils.getContextClassLoader());
    } finally {
        // reset the TCCL for other tests
        setTCCL(previousTCCL);
    }
}

