@Test
public void testClassLoaderIdenticalWithMultipleThreads() throws Exception {
    final Set<ClassLoader> clSet = Collections.synchronizedSet(new HashSet<>());
    final CountDownLatch countDownLatch = new CountDownLatch(50);
    for (int i = 0; i < 50; i++) {
        new Thread(() -> {
            try {
                clSet.add(cache.getProxyClassLoader(this.getClass().getClassLoader(), new Class<?>[] { Closeable.class, Client.class, HelloWorld.class }));
            } finally {
                countDownLatch.countDown();
            }
        }).start();
    }
    countDownLatch.await();
    assertSame(1, clSet.size());
}

