    MessagePartInfo mpi = new MessagePartInfo(new QName("", "B"), null);
    mpi.setTypeClass(InHeaderT.class);
    mi1.addMessagePart(mpi);
    mpi = new MessagePartInfo(new QName("", "D"), null);
    mpi.setTypeClass(OutHeaderT.class);
