    // nillable first
    QName element = elements.next();
    if ("minOccursProperty".equals(element.getLocalPart())) {
        assertEquals(1, info.getMinOccurs(element));
    } else {
        assertFalse(info.isNillable(element));
    }
    assertTrue(elements.hasNext());
    // minOccurs = 1 second
