@Test
public void testURIWithExtraPathMatchesOriginalURIPlusPath() {
    assertEquals("mailto:bob@apache.org", UriBuilder.fromUri("mailto:bob@apache.org").path("extra").build().toString());
    assertEquals("news:comp.lang.java", UriBuilder.fromUri("news:comp.lang.java").path("extra").build().toString());
    assertEquals("urn:isbn:096139210x", UriBuilder.fromUri("urn:isbn:096139210x").path("extra").build().toString());
    assertEquals("docs/guide/collections/designfaq.html/extra#28", UriBuilder.fromUri("docs/guide/collections/designfaq.html#28").path("extra").build().toString());
    assertEquals("../../../demo/jfc/SwingSet2/src/SwingSet2.java/extra", UriBuilder.fromUri("../../../demo/jfc/SwingSet2/src/SwingSet2.java").path("extra").build().toString());
    assertEquals("file:///~/calendar/extra", UriBuilder.fromUri("file:///~/calendar").path("extra").build().toString());
    assertEquals("bob@somehost.com/extra", UriBuilder.fromUri("bob@somehost.com").path("extra").build().toString());
    assertEquals("http://localhost/somePath/extra", UriBuilder.fromUri("http://localhost/somePath").path("extra").build().toString());
    assertEquals("http://localhost:1234/someOtherPath/extra", UriBuilder.fromUri("http://localhost:1234/someOtherPath").path("extra").build().toString());
    assertEquals("http://127.0.0.1/extra", UriBuilder.fromUri("http://127.0.0.1").path("extra").build().toString());
    assertEquals("http://127.0.0.1/extra", UriBuilder.fromUri("http://127.0.0.1/").path("extra").build().toString());
    assertEquals("http://127.0.0.1/index.html/extra", UriBuilder.fromUri("http://127.0.0.1/index.html").path("extra").build().toString());
    assertEquals("myscheme://a.host:7575/extra", UriBuilder.fromUri("myscheme://a.host:7575/").path("extra").build().toString());
    // note that this will use the scheme specific part of the URI, as opposed to host, port and path,
    // and therefore the extra path will not be appended. URI uses an int for the port, and therefore
    // will not parse the "fakePort" part of this URI as a port.
    assertEquals("myscheme://not.really.a.host:fakePort/", UriBuilder.fromUri("myscheme://not.really.a.host:fakePort/").path("extra").build().toString());
}

