@Test
public void testCompareNumberOfLiteralCharacters() {
    URITemplate t1 = new URITemplate("/foo");
    URITemplate t2 = new URITemplate("/bar");
    URITemplate t3 = new URITemplate("/foo/bar");
    assertEquals(0, URITemplate.compareTemplates(t1, t1));
    assertTrue(URITemplate.compareTemplates(t1, t3) > 0);
    assertTrue(URITemplate.compareTemplates(t3, t1) < 0);
    assertEquals(Integer.signum(URITemplate.compareTemplates(t1, t2)), -Integer.signum(URITemplate.compareTemplates(t2, t1)));
}

@Test
public void testNonCapturingGroup() {
    MultivaluedMap<String, String> values = new MetadataMap<>();
    URITemplate t1 = new URITemplate("/{name: (?:cxf|CXF)}");
    assertTrue("should match '/cxf' url", t1.match("/cxf", values));
    Assert.assertEquals("cxf", values.get("name").get(0));
    URITemplate t2 = new URITemplate("/{project: (?>cxf|apache)}");
    assertTrue("should match '/cxf' url", t2.match("/cxf", values));
    Assert.assertEquals("cxf", values.get("project").get(0));
}

