@Test
public void testPathEncode() {
    // rfc3986.txt 3.3
    //segment-nz = 1*pchar
    //pchar = unreserved / pct-encoded / sub-delims / ":" / "@"
    // sub-delims = "!" / "$" / "&" / "'" / "(" / ")" / "*" / "+" / "," / ";" / "="
    // unreserved = ALPHA / DIGIT / "-" / "." / "_" / "~"
    // '&' has to be represented as &amp; in WADL
    String pathChars = ":@!$&'()*+,;=-._~";
    String str = HttpUtils.pathEncode(pathChars);
    assertEquals(str, pathChars);
}

