@Test
public void testCompareMediaTypes() throws Exception {
    MediaType m1 = MediaType.valueOf("text/xml");
    MediaType m2 = MediaType.valueOf("text/*");
    assertTrue("text/xml is more specific than text/*", JAXRSUtils.compareMediaTypes(m1, m2) < 0);
    assertTrue("text/* is less specific than text/*", JAXRSUtils.compareMediaTypes(m2, m1) > 0);
    assertTrue("text/xml should be equal to itself", JAXRSUtils.compareMediaTypes(m1, new MediaType("text", "xml")) == 0);
    assertTrue("text/* should be equal to itself", JAXRSUtils.compareMediaTypes(m2, new MediaType("text", "*")) == 0);
    assertTrue("text/plain and text/xml are just two specific media types", JAXRSUtils.compareMediaTypes(MediaType.valueOf("text/plain"), m1) == 0);
    assertTrue("text/xml and text/plain are just two specific media types", JAXRSUtils.compareMediaTypes(m1, MediaType.valueOf("text/plain")) == 0);
    assertTrue("*/* is less specific than text/xml", JAXRSUtils.compareMediaTypes(JAXRSUtils.ALL_TYPES, m1) > 0);
    assertTrue("*/* is less specific than text/xml", JAXRSUtils.compareMediaTypes(m1, JAXRSUtils.ALL_TYPES) < 0);
    assertTrue("*/* is less specific than text/*", JAXRSUtils.compareMediaTypes(JAXRSUtils.ALL_TYPES, m2) > 0);
    assertTrue("*/* is less specific than text/*", JAXRSUtils.compareMediaTypes(m2, JAXRSUtils.ALL_TYPES) < 0);
    MediaType m3 = MediaType.valueOf("text/xml;q=0.2");
    assertTrue("text/xml should be more preferred than text/xml;q=0.2", JAXRSUtils.compareMediaTypes(m1, m3) < 0);
    MediaType m4 = MediaType.valueOf("text/xml;q=.3");
    assertTrue("text/xml;q=.3 should be more preferred than text/xml;q=0.2", JAXRSUtils.compareMediaTypes(m4, m3) < 0);
    assertTrue("text/xml;q=.3 should be more preferred than than text/xml;q=0.2", JAXRSUtils.compareMediaTypes(m3, m4) > 0);
}

@Test
public void testCompareSortedMediaTypes() throws Exception {
    MediaType m1 = MediaType.valueOf("text/xml");
    MediaType m2 = MediaType.valueOf("text/*");
    assertTrue("text/xml is more specific than text/*", compareSortedMediaTypes(Collections.singletonList(m1), Collections.singletonList(m2)) < 0);
    assertTrue("text/* is less specific than text/xml", compareSortedMediaTypes(Collections.singletonList(m2), Collections.singletonList(m1)) > 0);
    assertTrue("text/xml is the same as text/xml", compareSortedMediaTypes(Collections.singletonList(m1), Collections.singletonList(m1)) == 0);
    List<MediaType> sortedList1 = new ArrayList<>();
    sortedList1.add(m1);
    sortedList1.add(m2);
    List<MediaType> sortedList2 = new ArrayList<>();
    sortedList2.add(m1);
    sortedList2.add(m2);
    assertTrue("lists should be equal", compareSortedMediaTypes(sortedList1, sortedList2) == 0);
    sortedList1.add(MediaType.WILDCARD_TYPE);
    assertTrue("first list should be less specific", compareSortedMediaTypes(sortedList1, sortedList2) > 0);
    sortedList1.add(MediaType.WILDCARD_TYPE);
    assertTrue("second list should be more specific", compareSortedMediaTypes(sortedList2, sortedList1) < 0);
}

