    cri.setMethodDispatcher(md);
    OperationResourceInfo ori = JAXRSUtils.findTargetMethod(getMap(cri), createMessage(), "GET", new MetadataMap<String, String>(), "*/*", getTypes("text/plain"));
    assertSame(ori, ori2);
    ori = JAXRSUtils.findTargetMethod(getMap(cri), createMessage(), "GET", new MetadataMap<String, String>(), "*/*", getTypes("text/xml"));
    assertSame(ori, ori1);
    ori = JAXRSUtils.findTargetMethod(getMap(cri), createMessage(), "GET", new MetadataMap<String, String>(), "*/*", sortMediaTypes(getTypes("*/*;q=0.1,text/plain,text/xml;q=0.8")));
