    when(mockedBeanMgr.getReference(mockedBean, List.class, mockedCreationalCtx)).thenReturn(stringList);
    when(mockedBean.getScope()).thenReturn((Class) ApplicationScoped.class);
    when(mockedBeanMgr.isNormalScope(ApplicationScoped.class)).thenReturn(false);
    Bus bus = new ExtensionManagerBus();
    bus.setExtension(mockedBeanMgr, BeanManager.class);
    Instance<List> i = CDIUtils.getInstanceFromCDI(List.class, bus);
