@Test
public void testOnErrorCallbackIsCalled() throws WebApplicationException, IOException {
    when(writer.isWriteable(any(), any(), any(), any())).thenReturn(true);
    final LongAdder adder = new LongAdder();
    final SseEventSinkImpl sink = new SseEventSinkImpl(writer, null, ctx) {

        @Override
        public CompletionStage<?> send(OutboundSseEvent event) {
            ctx.start(() -> {
                throw new RuntimeException("Failed to schedule async task");
            });
            return CompletableFuture.completedFuture(null);
        }
    };
    broadcaster.register(sink);
    broadcaster.onError((s, ex) -> {
        if (s == sink) {
            adder.increment();
        }
    });
    assertThat(adder.intValue(), equalTo(0));
    broadcaster.broadcast(new OutboundSseEventImpl.BuilderImpl().build());
    broadcaster.close();
    assertThat(adder.intValue(), equalTo(1));
}

@Test
public void testCreateSseEventSinkWithDefaultBufferSize() {
    final SseEventSink sink = provider.createContext(message);
    IntStream.range(0, 10000).mapToObj(i -> sink.send(EVENT)).map(CompletionStage::toCompletableFuture).// At this point, buffer is full, but nothing has been delivered so far
    forEach(f -> assertThat(f.isDone(), equalTo(false)));
    // The buffer overflow should trigger message rejection and exceptional completion
    final CompletableFuture<?> overflow = sink.send(EVENT).toCompletableFuture();
    assertThat(overflow.isCompletedExceptionally(), equalTo(true));
    exception.expect(CompletionException.class);
    exception.expectMessage("The buffer is full (10000), unable to queue SSE event for send.");
    overflow.join();
}

