    m.put(LocalConduit.IN_CONDUIT, conduit);
    Exchange ex = new ExchangeImpl();
    ex.put(Bus.class, bus);
    m.setExchange(ex);
    Integer code = (Integer) m.get(Message.RESPONSE_CODE);
    assertNull(code);
    Conduit backChannel = d.getBackChannel(m);
