}

@Test
public void testWeblientPathRegularExpression() throws Exception {
    String endpointAddress = "http://localhost:" + PORT + "/bookstore/echoxmlbookregex";
    WebClient client = WebClient.create(endpointAddress);
    long id = 5678;
    Book book = new Book();
    book.setId(id);
    // Successful
    Book echoedBook = client.type("application/xml").accept("application/xml").path("/" + id).post(book, Book.class);
    assertEquals(id, echoedBook.getId());
    // Too long
    try {
        client.reset().type("application/xml").accept("application/xml").path("/" + 56789).post(book, Book.class);
        fail("Failure expected on a failing regex");
    } catch (NotFoundException ex) {
        // expected
    }
    // Too short
    try {
        client.reset().type("application/xml").accept("application/xml").path("/" + 56).post(book, Book.class);
        fail("Failure expected on a failing regex");
    } catch (NotFoundException ex) {
        // expected
    }
    // Wrong digits
    try {
        client.reset().type("application/xml").accept("application/xml").path("/" + 1234).post(book, Book.class);
        fail("Failure expected on a failing regex");
    } catch (NotFoundException ex) {
        // expected
    }
    // Finally try another successful call
    assertNotNull(client.reset().type("application/xml").accept("application/xml").path("/" + 8667).post(book, Book.class));
}

