@Test
public void testAddBookWithDetailsAsMultipartBadRequest() throws Exception {
    String address = "http://localhost:" + PORT + "/bookstore/books/details";
    final Client client = ClientBuilder.newClient();
    try (InputStream is = getClass().getResourceAsStream("/org/apache/cxf/systest/jaxrs/resources/attachmentData")) {
        final MultipartBody builder = new MultipartBody(Arrays.asList(new AttachmentBuilder().mediaType("application/xml").id("book").object(new BookWithValidation()).build(), new AttachmentBuilder().id("upfile1Detail").object(is).contentDisposition(new ContentDisposition("form-data; name=\"field1\";")).build(), new AttachmentBuilder().id("upfile2Detail").dataHandler(new DataHandler(new InputStreamDataSource(new ByteArrayInputStream(new byte[0]), "text/xml"))).contentDisposition(new ContentDisposition("form-data; name=\"field2\";")).build(), new AttachmentBuilder().id("upfile3Detail").dataHandler(new DataHandler(new InputStreamDataSource(new ByteArrayInputStream(new byte[0]), "text/xml"))).contentDisposition(new ContentDisposition("form-data; name=\"field3\";")).build()));
        final Response response = client.target(address).request("text/xml").post(Entity.entity(builder, "multipart/form-data"));
        // Book's name is 'null', validation should fail with 400
        assertThat("Unexpected status code for response:" + response, response.getStatus(), equalTo(400));
    }
}

@Test
public void testAddBookWithDetailsAsMultipart() throws Exception {
    String address = "http://localhost:" + PORT + "/bookstore/books/details";
    final Client client = ClientBuilder.newClient();
    try (InputStream is = getClass().getResourceAsStream("/org/apache/cxf/systest/jaxrs/resources/attachmentData")) {
        final MultipartBody builder = new MultipartBody(Arrays.asList(new AttachmentBuilder().mediaType("application/xml").id("book").object(new BookWithValidation("Book", "book1")).build(), new AttachmentBuilder().id("upfile1Detail").object(is).contentDisposition(new ContentDisposition("form-data; name=\"field1\";")).build(), new AttachmentBuilder().id("upfile2Detail").dataHandler(new DataHandler(new InputStreamDataSource(new ByteArrayInputStream(new byte[0]), "text/xml"))).contentDisposition(new ContentDisposition("form-data; name=\"field2\";")).build(), new AttachmentBuilder().id("upfile3Detail").dataHandler(new DataHandler(new InputStreamDataSource(new ByteArrayInputStream(new byte[0]), "text/xml"))).contentDisposition(new ContentDisposition("form-data; name=\"field3\";")).build()));
        final Response response = client.target(address).request("text/xml").post(Entity.entity(builder, "multipart/form-data"));
        final BookWithValidation book = response.readEntity(BookWithValidation.class);
        assertThat("Unexpected status code for response:" + response, response.getStatus(), equalTo(200));
        assertThat(book.getName(), equalTo("upfile1Detail,upfile2Detail,upfile3Detail"));
    }
}

