@Test
public void testCollapseNeeded() throws JAXBException, SAXException {
    for (String[] value : new String[][] { { "expected", " expected" }, { "expected", " expected " }, { "expected", " expected  " }, { "expected", "  expected" }, { "expected", "  expected  " }, { "expected expected", "  expected         expected" } }) {
