    InputStream is = getClass().getResourceAsStream("PingReq.xml");
    SOAPMessage outMsg = MessageFactory.newInstance().createMessage(null, is);
    SOAPMessage inMsg = disp.invoke(outMsg);
    assertNotNull(inMsg);
