    DocLitBareCodeFirstService.GreetMeRequest req = new DocLitBareCodeFirstService.GreetMeRequest();
    DocLitBareCodeFirstService.GreetMeResponse resp;
    BigInteger[] i;
    req.setName("Foo");
    resp = port.greetMe(req);
    assertEquals(req.getName(), resp.getName());
