        final Entity<MultipartBody> entity = Entity.entity(new MultipartBody(att), MediaType.MULTIPART_FORM_DATA_TYPE);
        try (Response response = webClient.header("Content-Type", MediaType.MULTIPART_FORM_DATA).async().post(entity).get(10, TimeUnit.SECONDS)) {
            assertThat(response.getStatus(), equalTo(201));
            assertThat(response.getHeaderString("Transfer-Encoding"), equalTo(chunked ? "chunked" : null));
            assertThat(response.getEntity(), not(equalTo(null)));
        }
    } finally {
        webClient.close();
    }
    assertRedirect(chunked + "_" + autoRedirect + "_" + filename);
}

