    LOG.fine("Created greeter client.");
    org.apache.cxf.endpoint.Endpoint ep = ClientProxy.getClient(greeter).getEndpoint();
    String epId = RMUtils.getEndpointIdentifier(ep, clientBus);
    // sent
    greeter.greetMeOneWay("one");
