@Test
public void testCreateSequenceRefused() throws Exception {
    init("org/apache/cxf/systest/ws/rm/limit-seqs.xml");
    RMManager manager = greeterBus.getExtension(RMManager.class);
    assertEquals("Unexpected maximum sequence count.", 1, manager.getDestinationPolicy().getMaxSequences());
    greeter.greetMe("one");
    //hold onto the greeter to keep the sequence open
    Closeable oldGreeter = (Closeable) greeter;
    // force greeter to be re-initialized so that a new sequence is created
    initProxy(false, null);
    try {
        greeter.greetMe("two");
        fail("Expected fault.");
    } catch (WebServiceException ex) {
        // sequence creation refused
    }
    // the third inbound message has a SequenceFault header
    MessageFlow mf = new MessageFlow(outRecorder.getOutboundMessages(), inRecorder.getInboundMessages(), Names200408.WSA_NAMESPACE_NAME, RM10Constants.NAMESPACE_URI);
    mf.verifySequenceFault(RM10Constants.CREATE_SEQUENCE_REFUSED_FAULT_QNAME, false, 2);
    String[] expectedActions = new String[3];
    expectedActions = new String[] { RM10Constants.CREATE_SEQUENCE_RESPONSE_ACTION, GREETME_RESPONSE_ACTION, RM10_GENERIC_FAULT_ACTION };
    mf.verifyActions(expectedActions, false);
    //now close the old greeter to cleanup the sequence
    oldGreeter.close();
}

@Test
public void testTimeout() throws Exception {
    init("org/apache/cxf/systest/ws/rm/rminterceptors.xml", true);
    List<Dispatch<DOMSource>> dispatches = new ArrayList<>(5);
    int count = 5;
    for (int x = 0; x < count; x++) {
        Dispatch<DOMSource> dispatch = initDispatch();
        AcksPolicyType ap = new AcksPolicyType();
        //don't send the acks to cause a memory leak - CXF-7096
        ap.setImmediaAcksTimeout(500000L);
        greeterBus.getExtension(RMManager.class).getDestinationPolicy().setAcksPolicy(ap);
        dispatch.invoke(getDOMRequest("One"));
        dispatches.add(dispatch);
    }
    RMEndpoint ep = rmManager.findReliableEndpoint(GREETME_SERVICE_NAME);
    Assert.assertNotNull(ep);
    Assert.assertEquals(count, ep.getDestination().getAllSequences().size());
    Assert.assertEquals(count, ep.getSource().getAllSequences().size());
    Thread.sleep(2500);
    System.gc();
    Assert.assertEquals(0, ep.getDestination().getAllSequences().size());
    Assert.assertEquals(0, ep.getSource().getAllSequences().size());
    try {
        dispatches.get(0).invoke(getDOMRequest("One"));
        fail("The sequence should have been terminated");
    } catch (Throwable t) {
        //expected
        assertTrue(t.getMessage().contains("not a known Sequence identifier"));
    }
    rmManager.getStore();
}

@Test
public void testDefaultInvocationHandling() throws Exception {
    setupGreeter();
    control.setRobustInOnlyMode(false);
    FaultLocation location = new org.apache.cxf.greeter_control.types.ObjectFactory().createFaultLocation();
    location.setPhase(Phase.INVOKE);
    location.setBefore(ServiceInvokerInterceptor.class.getName());
    RMManager manager = greeterBus.getExtension(RMManager.class);
    // the message is acked and the invocation takes place
    greeter.greetMeOneWay("one");
    waitForEmpty(manager.getRetransmissionQueue());
    control.setFaultLocation(location);
    // the invocation fails but the message is acked because the delivery succeeds
    greeter.greetMeOneWay("two");
    waitForEmpty(manager.getRetransmissionQueue());
}

@Test
public void testRobustInvocationHandling() throws Exception {
    setupGreeter();
    control.setRobustInOnlyMode(true);
    FaultLocation location = new org.apache.cxf.greeter_control.types.ObjectFactory().createFaultLocation();
    location.setPhase(Phase.INVOKE);
    location.setBefore(ServiceInvokerInterceptor.class.getName());
    RMManager manager = greeterBus.getExtension(RMManager.class);
    // the message is acked and the invocation takes place
    greeter.greetMeOneWay("one");
    waitForEmpty(manager.getRetransmissionQueue());
    control.setFaultLocation(location);
    // the invocation fails but the message is acked because the delivery succeeds
    greeter.greetMeOneWay("two");
    waitForNotEmpty(manager.getRetransmissionQueue());
    location.setPhase(null);
    control.setFaultLocation(location);
    // the retransmission succeeds and the invocation succeeds, the message is acked
    waitForEmpty(manager.getRetransmissionQueue());
}

