    assertEquals(boolean.class, paramTypes2[0]);
    assertEquals(1, paramAnns2[0].length);
    QueryParam test2QueryParam1 = (QueryParam) paramAnns2[0][0];
    assertEquals("snapshot", test2QueryParam1.value());
