    char[] chars = new char[100];
    int size = 0;
    StringBuilder sb = new StringBuilder();
    while (size < outputFile.length()) {
        int readLen = fileReader.read(chars);
        sb.append(chars, 0, readLen);
        size = size + readLen;
    }
    fileReader.close();
    String serviceString = new String(sb);
    assertTrue(serviceString.indexOf("<wsdl:types>") >= 0);
    assertTrue(serviceString.indexOf("<schema targetNamespace=\"http:/" + "/apache.org/Invoice\" xmlns=\"http:/" + "/www.w3.org/2001/XMLSchema\" xmlns:soap=\"http:/" + "/schemas.xmlsoap.org/wsdl/soap/\" xmlns:tns=\"http:/" + "/apache.org/Invoice\" xmlns:wsdl=\"http:/" + "/schemas.xmlsoap.org/wsdl/\">") >= 0);
    assertTrue(serviceString.indexOf("<complexType name=\"InvoiceHeader\">") >= 0);
}

